// cli_tool: MNIST inference for the 3-layer MLP in model.py.
// Usage: ./cli_tool weights.json image.png
// Prints only the predicted digit (0-9).

#include <cJSON.h>
#include <lodepng.h>

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <string>
#include <vector>

struct Linear {
    int out_dim = 0;
    int in_dim = 0;
    std::vector<float> w;  // row-major: w[o * in_dim + i]
    std::vector<float> b;  // bias[o]
};

struct Model {
    Linear layers[3];
};

static bool file_to_string(const char *path, std::string &out) {
    FILE *f = fopen(path, "rb");
    if (!f) return false;
    std::string s;
    char buf[65536];
    size_t n;
    while ((n = fread(buf, 1, sizeof buf, f)) > 0) s.append(buf, n);
    fclose(f);
    out = s;
    return true;
}

static std::vector<float> read_float_array(const cJSON *arr, int expected) {
    std::vector<float> out;
    int n = (arr && cJSON_IsArray(arr)) ? (int)cJSON_GetArraySize(arr) : 0;
    if (n != expected) return out;
    out.reserve(n);
    for (int i = 0; i < n; i++) {
        const cJSON *it = cJSON_GetArrayItem(arr, i);
        if (!it || !cJSON_IsNumber(it)) { out.clear(); return out; }
        out.push_back((float)it->valuedouble);
    }
    return out;
}

static bool load_model(const char *path, Model &m) {
    std::string text;
    if (!file_to_string(path, text)) return false;

    cJSON *root = cJSON_Parse(text.c_str());
    if (!root) return false;
    cJSON *layers = cJSON_GetObjectItem(root, "layers");
    if (!layers || !cJSON_IsArray(layers) || cJSON_GetArraySize(layers) != 3) {
        cJSON_Delete(root);
        return false;
    }
    for (int li = 0; li < 3; li++) {
        const cJSON *L = cJSON_GetArrayItem(layers, li);
        if (!L || !cJSON_IsObject(L)) { cJSON_Delete(root); return false; }
        const cJSON *sw = cJSON_GetObjectItem(L, "shape_w");
        const cJSON *sb = cJSON_GetObjectItem(L, "shape_b");
        if (!sw || !cJSON_IsArray(sw) || cJSON_GetArraySize(sw) != 2) { cJSON_Delete(root); return false; }
        if (!sb || !cJSON_IsArray(sb) || cJSON_GetArraySize(sb) != 1) { cJSON_Delete(root); return false; }
        int out_dim = (int)cJSON_GetArrayItem(sw, 0)->valuedouble;
        int in_dim = (int)cJSON_GetArrayItem(sw, 1)->valuedouble;
        if (out_dim <= 0 || in_dim <= 0 || (int)cJSON_GetArrayItem(sb, 0)->valuedouble != out_dim) {
            cJSON_Delete(root);
            return false;
        }
        std::vector<float> w = read_float_array(cJSON_GetObjectItem(L, "weight"), out_dim * in_dim);
        std::vector<float> b = read_float_array(cJSON_GetObjectItem(L, "bias"), out_dim);
        if (w.empty() || b.empty()) { cJSON_Delete(root); return false; }
        m.layers[li].out_dim = out_dim;
        m.layers[li].in_dim = in_dim;
        m.layers[li].w = std::move(w);
        m.layers[li].b = std::move(b);
    }
    cJSON_Delete(root);
    return true;
}

// Bilinear-resize a gray image (w x h, row-major) to 28x28.
static std::vector<float> resize_gray(const std::vector<float> &in, int in_w, int in_h, int out_w, int out_h) {
    std::vector<float> out(out_w * out_h);
    for (int oy = 0; oy < out_h; oy++) {
        float fy = (oy + 0.5f) * (float)in_h / (float)out_h - 0.5f;
        int y0 = (int)floorf(fy);
        float ty = fy - y0;
        int y1 = y0 + 1;
        if (y0 < 0) y0 = 0;
        if (y1 < 0) y1 = 0;
        if (y0 >= in_h) y0 = in_h - 1;
        if (y1 >= in_h) y1 = in_h - 1;
        for (int ox = 0; ox < out_w; ox++) {
            float fx = (ox + 0.5f) * (float)in_w / (float)out_w - 0.5f;
            int x0 = (int)floorf(fx);
            float tx = fx - x0;
            int x1 = x0 + 1;
            if (x0 < 0) x0 = 0;
            if (x1 < 0) x1 = 0;
            if (x0 >= in_w) x0 = in_w - 1;
            if (x1 >= in_w) x1 = in_w - 1;
            float top = in[y0 * in_w + x0] * (1.f - tx) + in[y0 * in_w + x1] * tx;
            float bot = in[y1 * in_w + x0] * (1.f - tx) + in[y1 * in_w + x1] * tx;
            out[oy * out_w + ox] = top * (1.f - ty) + bot * ty;
        }
    }
    return out;
}

// Decode the PNG to a 784-dim input vector with values in [0, 1].
static bool image_to_input(const char *path, std::vector<float> &x) {
    unsigned char *rgba = nullptr;
    unsigned w = 0, h = 0;
    unsigned err = lodepng_decode32_file(&rgba, &w, &h, path);
    if (err) {
        fprintf(stderr, "lodepng error %u: %s\n", err, lodepng_error_text(err));
        return false;
    }
    if (!w || !h) {
        free(rgba);
        return false;
    }
    std::vector<float> gray((size_t)w * h);
    for (size_t i = 0; i < (size_t)w * h; i++) {
        float r = rgba[4 * i], g = rgba[4 * i + 1], b = rgba[4 * i + 2];
        gray[i] = (0.2126f * r + 0.7152f * g + 0.0722f * b) / 255.0f;
    }
    free(rgba);

    if ((int)w != 28 || (int)h != 28) {
        gray = resize_gray(gray, (int)w, (int)h, 28, 28);
    }
    x = std::move(gray);
    return true;
}

static inline float relu(float v) { return v > 0.f ? v : 0.f; }

static void linear_forward(const Linear &L, const float *in, float *out) {
    for (int o = 0; o < L.out_dim; o++) {
        float acc = L.b[o];
        const float *row = L.w.data() + (size_t)o * L.in_dim;
        for (int i = 0; i < L.in_dim; i++) acc += row[i] * in[i];
        out[o] = acc;
    }
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "usage: %s weights.json image.png\n", argv[0]);
        return 2;
    }
    Model model;
    if (!load_model(argv[1], model)) {
        fprintf(stderr, "failed to load weights from %s\n", argv[1]);
        return 1;
    }
    std::vector<float> x;
    if (!image_to_input(argv[2], x)) {
        fprintf(stderr, "failed to load image %s\n", argv[2]);
        return 1;
    }
    if ((int)x.size() != model.layers[0].in_dim) {
        fprintf(stderr, "image has %zu pixels, model expects %d\n", x.size(), model.layers[0].in_dim);
        return 1;
    }

    std::vector<float> h1(model.layers[0].out_dim);
    std::vector<float> h2(model.layers[1].out_dim);
    std::vector<float> out(model.layers[2].out_dim);

    linear_forward(model.layers[0], x.data(), h1.data());
    for (int i = 0; i < (int)h1.size(); i++) h1[i] = relu(h1[i]);
    linear_forward(model.layers[1], h1.data(), h2.data());
    for (int i = 0; i < (int)h2.size(); i++) h2[i] = relu(h2[i]);
    linear_forward(model.layers[2], h2.data(), out.data());

    int best = 0;
    float best_v = out[0];
    for (int i = 1; i < (int)out.size(); i++) {
        if (out[i] > best_v) { best_v = out[i]; best = i; }
    }
    printf("%d\n", best);
    return 0;
}

